Pi=math.pi;Tau=math.pi*2;Sin=math.sin;Cos=math.cos;Tan=math.tan;Acos=math.acos;Asin=math.asin;Atan=math.atan;Sqrt=math.sqrt;Max=math.max;Min=math.min;Floor=math.floor;Ceil=math.ceil;Abs=math.abs;function Clamp(a,b,c)return Min(Max(a,b),c)end;function Lerp(a,b,c)return a+(b-a)*c end;function Map(a,b,c,d,e)return((a-b)/(c-b))*(e-d)+d end;function Round(a)return Floor(a+0.5)end;function Vec(a,b,c)return{x=a,y=b,z=c}end;function Add(a,b)return{x=a.x+b.x,y=a.y+b.y,z=a.z+b.z}end;function Sub(a,b)return{x=a.x-b.x,y=a.y-b.y,z=a.z-b.z}end;function Scale(a,b)return{x=a.x*b,y=a.y*b,z=a.z*b}end;function Dot(a,b)return a.x*b.x+a.y*b.y+a.z*b.z end;function Cross(a,b)return{x=a.y*b.z-a.z*b.y,y=a.z*b.x-a.x*b.z,z=a.x*b.y-a.y*b.x}end;function Len(a)return Sqrt(a.x*a.x+a.y*a.y+a.z*a.z)end;function SetLen(a,b)return Scale(Norm(a),b)end;function Norm(a)return Len(a)~=0 and Scale(a,1/Len(a))or{x=0,y=0,z=0}end;function Lerp(a,b,c)return Add(a,Scale(Sub(b,a),c))end;function IJK(a,b,c)local d,e,f=Cos(a),Cos(b),Cos(c)local a,b,c=Sin(a),Sin(b),Sin(c)return Vec(Vec(e*f,e*c,-b),Vec(-d*c+a*b*f,d*f+a*b*c,a*e),Vec(d*b*f+a*c,d*b*c-a*f,d*e))end;function Local(a,b)return Vec(Dot(a,b.x),Dot(a,b.y),Dot(a,b.z))end;function Global(a,b)return Add(Scale(b.x,a.x),Add(Scale(b.y,a.y),Scale(b.z,a.z)))end;function Sphere(a)return Vec(Atan(a.x,a.y),Asin(a.z/Len(a)),Len(a))end;function Cartesian(a)return Vec(a.z*Cos(a.y)*Sin(a.x),a.z*Cos(a.y)*Cos(a.x),a.z*Sin(a.y))end;launched=false;state=0;debug_state=0;elapsed=0;target=Vec(0,0,0)waypoints={}aimpoint=Vec(0,0,0)radar_enabled=false;GUIDE_DELAY=property.getNumber("Guidance Delay")BOOST_DELAY=property.getNumber("Booster Delay")AUXILIARY_DELAY=property.getNumber("Auxiliary Delay")MODE=property.getNumber("Mode")EJECT_DIRECTION=property.getNumber("Eject Direction")EJECT_DURATION=property.getNumber("Eject Duration")ALTITUDE_MODE=property.getBool("Altitude Mode")ROLL_CONTROL=property.getBool("Active Roll Control")CRUISE_PATTERN=property.getNumber("Cruise Pattern")CRUISE_ALTITUDE=property.getNumber("Altitude")MAX_ANGLE=property.getNumber("Max Angle")ALTITUDE_GAIN=property.getNumber("Altitude Gain")FLATTEN_LARGE_TURN=property.getBool("Restrict Pitch During Turns")TERRAIN_MARGIN=property.getNumber("Terrain Follow Margin")TERMINAL_DISTANCE=property.getNumber("Terminal Distance")TERMINAL_PATTERN=property.getNumber("Terminal Pattern")EVASION_ANGLE=property.getNumber("Evasion Angle")TERMINAL_ALTITUDE=property.getNumber("Pop-up Height")DIVE_ANGLE=property.getNumber("Dive Angle")RADAR_TYPE=property.getNumber("Input Type")ALLOW_LOCK=property.getNumber("Allow Acquire")RADAR_PRIORITY=property.getNumber("Prioritise")TOLERANCE=property.getNumber("Tolerance")X_GAIN=property.getNumber("Pitch Gain")X_TRIM=property.getNumber("Pitch Trim")Y_GAIN=property.getNumber("Yaw Gain")Y_TRIM=property.getNumber("Yaw Trim")R_GAIN=property.getNumber("Roll Gain")R_TRIM=property.getNumber("Roll Trim")EXPONENT=property.getNumber("Guidance Exponent")AOA=property.getNumber("Level Angle")MARGIN=property.getNumber("Margin")function onTick()guidance=Vec(0,0,0)self={x=input.getNumber(1),y=input.getNumber(2),z=input.getNumber(3),rx=input.getNumber(4),ry=input.getNumber(5),rz=input.getNumber(6),pitch=input.getNumber(15),roll=input.getNumber(16)}self.IJK=IJK(self.rx,self.ry,self.rz)radar={x=(input.getNumber(10)/8)*Tau,y=(input.getNumber(11)/8)*Tau}if input.getBool(1)then launched=true end;if launched==true then elapsed=elapsed+1 end;g_delta=Sub(target,self)g_delta_flat=Vec(g_delta.x,0,g_delta.z)if elapsed>AUXILIARY_DELAY then output.setBool(3,true)end;if elapsed>BOOST_DELAY then output.setBool(1,true)end;output.setBool(2,radar_enabled)if state==0 then if MODE==0 then if input.getNumber(7)~=0 then target=Vec(input.getNumber(7),input.getNumber(8),input.getNumber(9))end elseif MODE==1 then if input.getBool(2)then if input.getNumber(7)~=0 then waypoints.insert(Vec(input.getNumber(7),input.getNumber(8),input.getNumber(9)))end;target=waypoints[1]elseif input.getBool(3)then waypoints={}end end;if launched==true then state=1 end elseif state==1 then if EJECT_DIRECTION~=0 then if elapsed<=EJECT_DURATION then if EJECT_DIRECTION==1 then guidance.y=1 elseif EJECT_DIRECTION==2 then guidance.y=-1 elseif EJECT_DIRECTION==3 then guidance.x=-1 elseif EJECT_DIRECTION==4 then guidance.x=1 end end end;if elapsed>Max(GUIDE_DELAY,EJECT_DURATION)then state=2 end;if elapsed<=EJECT_DURATION then debug_state=3 end;if elapsed<=GUIDE_DELAY and elapsed>EJECT_DURATION then debug_state=2 end;if elapsed>BOOST_DELAY and elapsed>EJECT_DURATION then debug_state=1 end elseif state==2 then if CRUISE_PATTERN==0 then aimpoint=g_delta;debug_state=5 elseif CRUISE_PATTERN==1 then if ALTITUDE_MODE==0 then altitude_setpoint=CRUISE_ALTITUDE else altitude_setpoint=CRUISE_ALTITUDE+target.y end;pitch_setpoint=Clamp((altitude_setpoint-self.y)*ALTITUDE_GAIN,-MAX_ANGLE,MAX_ANGLE)+AOA;aimpoint=Vec(g_delta.x,(math.tan(pitch_setpoint))*Len(g_delta_flat),g_delta.z)elseif CRUISE_PATTERN==2 then elseif CRUISE_ALTITUDE==3 then end;if FLATTEN_LARGE_TURN then if Dot(Norm(aimpoint),Norm(self.IJK.x))<0 then aimpoint.y=0 end end;if MODE==0 then if Len(g_delta)<TERMINAL_DISTANCE then state=3 end elseif MODE~=0 then if Len(g_delta)<TERMINAL_DISTANCE and#waypoints==1 then state=3 elseif Len(g_delta)<MARGIN and#waypoints>1 then table.remove(waypoints,1)target=waypoints[1]end end;if ALLOW_LOCK==0 then radar_enabled=true end;guidance=Sphere(Local(aimpoint,self.IJK))elseif state==3 then if TERMINAL_PATTERN==0 then aimpoint=g_delta elseif TERMINAL_PATTERN==1 then elseif TERMINAL_PATTERN==2 then end;if ALLOW_LOCK==1 then radar_enabled=true end end;if launched and ROLL_CONTROL then guidance.z=-self.roll else guidance.z=0 end;output.setNumber(1,Clamp(((guidance.x/Pi)^EXPONENT*X_GAIN)+X_TRIM,-1,1))output.setNumber(2,Clamp(((guidance.y/Pi)^EXPONENT*Y_GAIN)+Y_TRIM,-1,1))output.setNumber(3,Clamp(((guidance.z)*R_GAIN)+R_TRIM,-1,1))output.setNumber(4,debug_state)output.setNumber(8,Round(Len(g_delta)))end